import { NextResponse, type NextRequest } from "next/server";
import { requireActor } from "@/app/_lib/firm/actor";
import { adminSupabase } from "@/app/_lib/supabase/admin";
import { revalidateUser } from "@compound/db-cache";
import type { ProviderId } from "@/app/_lib/integrations/providers";
import { revokeProviderGrant } from "@/app/_lib/integrations/revoke";
import { isDemoEmail, DEMO_READONLY_MESSAGE } from "@/app/_lib/demo";

export const runtime = "nodejs";

// Disconnect an integration: revoke the grant with the PROVIDER, then drop the
// owner-readable invoices_integrations row AND the encrypted per-user token in
// invoices_oauth_tokens, so the provider falls back to "Not connected" and can be
// re-connected cleanly. Idempotent — disconnecting an already-disconnected
// provider is a no-op success. We never touch the user's synced invoices/clients
// here; this only severs the rail.
//
// Revocation comes FIRST and gates the delete. Intuit's publishing requirements
// mandate that disconnect revokes the access + refresh tokens, and the refresh
// token is the only thing that can perform that revocation — so if we deleted our
// rows first and the revoke then failed, the user's QuickBooks company would stay
// granted to us permanently with no way left to sever it. When revocation fails
// retryably we abort and say so, rather than reporting a disconnect we didn't do.
export async function POST(req: NextRequest) {
  const actor = await requireActor();
  if (!actor) return NextResponse.json({ error: "unauthorized" }, { status: 401 });
  const { authUser: user, ownerId } = actor;
  if (isDemoEmail(user.email)) {
    return NextResponse.json({ error: DEMO_READONLY_MESSAGE }, { status: 403 });
  }

  const { provider } = (await req.json().catch(() => ({}))) as { provider?: ProviderId };
  if (!provider) return NextResponse.json({ error: "provider required" }, { status: 400 });

  // Sever the grant provider-side before we lose the token that lets us do it.
  const revoked = await revokeProviderGrant(ownerId, provider);
  if (revoked.status === "failed") {
    console.error(
      `[invoices] disconnect aborted: ${provider} revocation failed for ${ownerId}: ${revoked.detail}`,
    );
    return NextResponse.json(
      {
        error: revoked.retryable
          ? "Could not reach the provider to revoke access. Nothing was changed — please try again."
          : "Could not revoke access with the provider. Nothing was changed.",
        provider,
      },
      { status: revoked.retryable ? 503 : 502 },
    );
  }

  const sb = adminSupabase();

  const { error: intErr } = await sb
    .from("invoices_integrations")
    .delete()
    .eq("user_id", ownerId)
    .eq("provider", provider);
  if (intErr) return NextResponse.json({ error: intErr.message }, { status: 500 });

  // Best-effort token teardown — the encrypted store is separate from the
  // integrations row, so clear it too. A missing row is not an error.
  await sb
    .from("invoices_oauth_tokens")
    .delete()
    .eq("user_id", ownerId)
    .eq("provider", provider);

  revalidateUser("invoices", ["integrations"], ownerId);
  return NextResponse.json({ ok: true, revoked: revoked.status });
}
