import { NextResponse } from "next/server";
import { requireActor } from "@/app/_lib/firm/actor";
import { adminSupabase } from "@/app/_lib/supabase/admin";

export const runtime = "nodejs";

// GDPR data export — every invoices_* row owned by the user, as one JSON file.
// ALWAYS the AUTH user's own data: while acting as a managed client this
// refuses rather than exporting someone else's book under the wrong identity.
export async function GET() {
  const actor = await requireActor();
  if (!actor) return NextResponse.json({ error: "unauthorized" }, { status: 401 });
  if (actor.actingFor) {
    return NextResponse.json(
      { error: "Switch back to your own account to export data." },
      { status: 403 },
    );
  }
  const user = actor.authUser;

  const sb = adminSupabase();
  const tables = [
    "invoices_clients",
    "invoices_invoices",
    "invoices_reminders",
    "invoices_cadence",
    "invoices_voice",
    "invoices_integrations",
  ];
  const out: Record<string, unknown> = {};
  for (const t of tables) {
    const { data } = await sb.from(t).select("*").eq("user_id", user.id);
    out[t] = data ?? [];
  }
  return new NextResponse(JSON.stringify(out, null, 2), {
    headers: {
      "content-type": "application/json",
      "content-disposition": `attachment; filename="tally-export-${Date.now()}.json"`,
    },
  });
}

